/// Looks up a culture by its full name, case-insensitively like .NET's
/// `CultureInfo.GetCultureInfo`. No parent fallback: `"de-XX"` is not `"de"`,
/// because .NET would resolve it against the whole CLDR tree and we only have
/// the cultures in [`CULTURES`].
pub(super) fn lookup(name: &str) -> Option<&'static CultureData> {
    let index = CULTURES
        .binary_search_by(|culture| ascii_lowercase_cmp(culture.name, name))
        .ok()?;
    Some(&CULTURES[index])
}

/// Orders two culture names the way [`CULTURES`] is sorted. Culture names are
/// ASCII, so a byte-wise ASCII-lowercase comparison is a full case-insensitive
/// match, and a non-ASCII argument simply matches nothing.
fn ascii_lowercase_cmp(a: &str, b: &str) -> std::cmp::Ordering {
    a.bytes()
        .map(|byte| byte.to_ascii_lowercase())
        .cmp(b.bytes().map(|byte| byte.to_ascii_lowercase()))
}
